using System.Collections.ObjectModel; using TP_ControlVehicular.Negocio.DTOs; using TP_ControlVehicular.Negocio.Interfaces; using TP_ControlVehicular.Negocio.Services; using UsuarioEntidad=TP_ControlVehicular.Entidad.Usuario;
namespace TP_ControlVehicular.Presentacion.ViewModels; public class UsuarioViewModel(RegistrarUsuarioHandler h,IUsuarioRepository u,IRolRepository r,AutoMapper.IMapper m):BaseViewModel { public ObservableCollection<UsuarioDto> Usuarios{get;}=new(); public ObservableCollection<RolDto> Roles{get;}=new(); public int IdUsuario{get;set;} public int IdRol{get;set;} public string Nombre{get;set;}=""; public string Contrasena{get;set;}=""; public bool Estado{get;set;}=true; public async Task LoadAsync(){Usuarios.Clear();Roles.Clear();foreach(var x in await u.GetActivosAsync())Usuarios.Add(m.Map<UsuarioDto>(x));foreach(var x in await r.GetActivosAsync())Roles.Add(m.Map<RolDto>(x));} public async Task GuardarAsync(){var x=new UsuarioEntidad{IdUsuario=IdUsuario,IdRol=IdRol,Nombre=Nombre,Contrasena=Contrasena,Estado=Estado};var d=await h.HandleAsync(x);var old=Usuarios.FirstOrDefault(a=>a.IdUsuario==d.IdUsuario);if(old!=null)Usuarios[Usuarios.IndexOf(old)]=d;else Usuarios.Add(d);} }
